"""Five-field cron expression parser."""
from models import FIELDS, CronSchedule


def _atom(token, spec):
    value = spec.names.get(token)
    if value is None:
        if not token.isdigit():
            raise ValueError(f"invalid {spec.name} token: {token!r}")
        value = int(token)
    return value


def _bounds(token, spec):
    if token == "*":
        return spec.minimum, spec.maximum
    if "-" in token:
        low_token, _, high_token = token.partition("-")
        return _atom(low_token, spec), _atom(high_token, spec)
    return _atom(token, spec), spec.maximum


def parse_field(expr, spec):
    """Parse one cron field into a frozenset of integers."""
    if not isinstance(expr, str) or not expr.strip():
        raise ValueError("empty cron field")
    values = set()
    for part in expr.split(","):
        if "/" in part:
            range_part, _, step_part = part.partition("/")
            step = int(step_part)
            low, high = _bounds(range_part, spec)
            values.update(range(low, high + 1, step))
        elif part == "*":
            values.update(range(spec.minimum, spec.maximum + 1))
        elif "-" in part:
            low, high = _bounds(part, spec)
            values.update(range(low, high + 1))
        else:
            values.add(_atom(part, spec))
    return frozenset(values)


def parse(expr):
    """Parse a 5-field cron expression into a CronSchedule."""
    if not isinstance(expr, str):
        raise ValueError("cron expression must be a string")
    parts = expr.split(" ")
    if len(parts) != len(FIELDS):
        raise ValueError(f"expected {len(FIELDS)} fields, got {len(parts)}")
    values = [parse_field(part, spec) for part, spec in zip(parts, FIELDS)]
    return CronSchedule(*values)

"""Cron schedule matching against datetimes."""


def cron_weekday(dt):
    """cron weekday for a datetime."""
    return dt.weekday()


def matches(schedule, dt):
    """True when dt's wall-clock fields satisfy the schedule."""
    return (
        dt.minute in schedule.minute
        and dt.hour in schedule.hour
        and dt.month in schedule.month
        and dt.day in schedule.day
        and cron_weekday(dt) in schedule.weekday
    )

"""Next-run enumeration for cron schedules."""
from datetime import datetime, timedelta, timezone

from zoneinfo import ZoneInfo

from matcher import matches


def next_runs(schedule, after, tz, count):
    """Return the next `count` matching instants at or after `after`."""
    if isinstance(tz, str):
        tz = ZoneInfo(tz)
    if count < 1:
        raise ValueError("count must be positive")
    naive = after.astimezone(tz).replace(second=0, microsecond=0).replace(tzinfo=None)
    results = []
    while len(results) < count:
        if matches(schedule, naive):
            results.append(naive.replace(tzinfo=tz))
        naive += timedelta(minutes=1)
    return results


def next_run(schedule, after, tz):
    return next_runs(schedule, after, tz, 1)[0]
